method total_match(lst1: seq<string>, lst2: seq<string>) returns (result: seq<string>)
    requires true
    ensures (|lst1| < |lst2| ==> result == lst1) &&
            (|lst1| > |lst2| ==> result == lst2) &&
            (|lst1| == |lst2| ==> result == lst1) &&
            (forall i :: 0 <= i < |lst1| ==> |lst1[i]|) &&
            (forall i :: 0 <= i < |lst2| ==> |lst2[i]|)
{
    var sum1 := 0;
    var sum2 := 0;

    // Calculate total number of characters in lst1
    var i := 0;
    while i < |lst1|
        invariant 0 <= i <= |lst1|
        invariant sum1 == (if i == 0 then 0 else sum1 + |lst1[i - 1]|)
    {
        sum1 := sum1 + |lst1[i]|;
        i := i + 1;
    }

    // Calculate total number of characters in lst2
    i := 0;
    while i < |lst2|
        invariant 0 <= i <= |lst2|
        invariant sum2 == (if i == 0 then 0 else sum2 + |lst2[i - 1]|)
    {
        sum2 := sum2 + |lst2[i]|;
        i := i + 1;
    }

    // Compare the sums and return the appropriate list
    if sum1 < sum2 {
        result := lst1;
    } else {
        result := lst2;
    }
}
